DECLARE @no varchar(31)=?,@name nvarchar(642)=?,@class bigint=?,@s1 varchar(2)=?,@s2 varchar(2)=?,@s3 varchar(2)=?,@s4 varchar(2)=?; DECLARE @offset int=?,@size int=?; SELECT CONVERT(varchar(19),s.student_id),s.student_no,s.student_name,s.student_name_kana,CONVERT(char(10),s.birth_date,23),c.school_year,COALESCE(g.code_name,N'不整合'),c.class_code,c.class_name,COALESCE(e.code_name,N'不整合') FROM dbo.m_student s LEFT JOIN dbo.m_class c ON c.class_id=s.class_id LEFT JOIN dbo.m_code g ON g.category_id=c.grade_category AND g.code_value=c.grade_code LEFT JOIN dbo.m_code e ON e.category_id=s.enrollment_category AND e.code_value=s.enrollment_status_code LEFT JOIN dbo.m_code p ON p.category_id=s.prefecture_category AND p.code_value=s.prefecture_code WHERE s.is_deleted=0 AND (@no IS NULL OR s.student_no LIKE @no ESCAPE '!') AND (@name IS NULL OR s.name_key LIKE @name ESCAPE '!') AND (@class IS NULL OR s.class_id=@class) AND ((@s1 IS NULL AND @s2 IS NULL AND @s3 IS NULL AND @s4 IS NULL) OR s.enrollment_status_code IN (@s1,@s2,@s3,@s4)) ORDER BY s.name_key DESC,s.student_id ASC OFFSET @offset ROWS FETCH NEXT @size ROWS ONLY;
